class Facturacion {
public:
std::string Operation1() const {
return "Facturacion: Ready!\n";
}
std::string OperationN() const {
return "Facturacion: Go!\n";
}};
class Compras {
public:
std::string Operation1() const {
return "Compras: Get ready!\n";
}
std::string OperationZ() const {
return "Compras: Fire!\n";
}};
class Operador {
protected:
Facturacion *Facturacion_;
Compras *Compras_;
public:
Operador(
Facturacion *Facturacion = nullptr,
Compras *Compras = nullptr) {
this->Facturacion_ = Facturacion ?: new Facturacion;
this->Compras_ = Compras ?: new Compras;
}
~Operador() {
delete Facturacion_;
delete Compras_;
}
std::string Operation() {
std::string result = "Operador initializes subsystems:\n";
result += this->Facturacion_->Operation1();
result += this->Compras_->Operation1();
    result += "Operador orders subsystems to perform the action:\n";
    result += this->Facturacion_->OperationN();
    result += this->Compras_->OperationZ();
    return result;
  }
};
void ClientCode(Operador *Operador) {
  std::cout << Operador->Operation();
}
int main() {
  Facturacion *Facturacion = new Facturacion;
  Compras *Compras = new Compras;
  Operador *Operador = new Operador(Facturacion, Compras);
  ClientCode(Operador);
  delete Operador;
  return 0;
}
